### 2.2 CloudWatch Container Insights

**Container Insights Configuration**:

```yaml
apiVersion: v1
kind: ConfigMap
metadata:
    name: cwagentconfig
    namespace: amazon-cloudwatch
data:
    cwagentconfig.json: |
        {
          "logs": {
            "metrics_collected": {
              "kubernetes": {
                "cluster_name": "fusion-eks-cluster",
                "metrics_collection_interval": 60
              }
            }
          },
          "metrics": {
            "namespace": "CWAgent",
            "metrics_collected": {
              "cpu": {
                "measurement": ["cpu_usage_idle", "cpu_usage_iowait"],
                "metrics_collection_interval": 60
              },
              "disk": {
                "measurement": ["used_percent"],
                "metrics_collection_interval": 60,
                "resources": ["*"]
              },
              "mem": {
                "measurement": ["mem_used_percent"],
                "metrics_collection_interval": 60
              }
            }
          }
        }
```

