### 7.2 Standard Dashboards

**Cluster Overview Dashboard**:

```json
{
    "dashboard": {
        "title": "Fusion EKS Cluster Overview",
        "panels": [
            {
                "title": "Cluster CPU Usage",
                "type": "stat",
                "targets": [
                    {
                        "expr": "100 - (avg(irate(node_cpu_seconds_total{mode=\"idle\"}[5m])) * 100)"
                    }
                ]
            },
            {
                "title": "Cluster Memory Usage",
                "type": "stat",
                "targets": [
                    {
                        "expr": "(1 - (node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes)) * 100"
                    }
                ]
            },
            {
                "title": "Pod Status",
                "type": "piechart",
                "targets": [
                    {
                        "expr": "count by (phase) (kube_pod_status_phase)"
                    }
                ]
            },
            {
                "title": "Request Rate by Service",
                "type": "graph",
                "targets": [
                    {
                        "expr": "sum(rate(fusion_http_requests_total[5m])) by (service)"
                    }
                ]
            }
        ]
    }
}
```

**Application Dashboard Template**:

```json
{
    "dashboard": {
        "title": "Fusion {{ .service_name }} Dashboard",
        "templating": {
            "list": [
                {
                    "name": "namespace",
                    "type": "query",
                    "query": "label_values(kube_pod_info, namespace)"
                },
                {
                    "name": "service",
                    "type": "query",
                    "query": "label_values(fusion_http_requests_total{namespace=\"$namespace\"}, service)"
                }
            ]
        },
        "panels": [
            {
                "title": "Request Rate",
                "type": "graph",
                "targets": [
                    {
                        "expr": "sum(rate(fusion_http_requests_total{service=\"$service\"}[5m])) by (endpoint)"
                    }
                ]
            },
            {
                "title": "Error Rate",
                "type": "graph",
                "targets": [
                    {
                        "expr": "sum(rate(fusion_http_requests_total{service=\"$service\",status_code=~\"5..\"}[5m])) / sum(rate(fusion_http_requests_total{service=\"$service\"}[5m])) * 100"
                    }
                ]
            },
            {
                "title": "Response Time Percentiles",
                "type": "graph",
                "targets": [
                    {
                        "expr": "histogram_quantile(0.50, sum(rate(fusion_http_request_duration_seconds_bucket{service=\"$service\"}[5m])) by (le))"
                    },
                    {
                        "expr": "histogram_quantile(0.95, sum(rate(fusion_http_request_duration_seconds_bucket{service=\"$service\"}[5m])) by (le))"
                    },
                    {
                        "expr": "histogram_quantile(0.99, sum(rate(fusion_http_request_duration_seconds_bucket{service=\"$service\"}[5m])) by (le))"
                    }
                ]
            }
        ]
    }
}
```
